/// <summary>
/// The decision the runtime returns for a single tool call or step during a run.
///   - "replay": return <c>result</c> without executing
///   - "execute": execute, then report the result back via <c>recordResult</c>
///   - "pause": stop the run (the binding throws the pause sentinel)
/// </summary>
[<RequireQualifiedAccess; TypeScriptTaggedUnion("kind", CaseRules.None)>]
type ToolDecision =
    | [<CompiledName("replay")>] Replay of result: obj
    | [<CompiledName("execute")>] Execute of seq: float
    | [<CompiledName("pause")>] Pause of seq: float

type CodemodeRuntime =
    /// <summary>
    /// Begin a fresh execution. Returns the execution id. Prunes old terminal
    /// executions down to <c>maxExecutions</c> (newest kept). The connector names the
    /// runtime was created with are recorded on the execution so a later resume
    /// can verify they are still configured.
    /// </summary>
    abstract ``begin``: code: string * ?options: CodemodeRuntime.Begin.Options -> JS.Promise<string>
    /// <summary>
    /// Resume an execution for a replay run. Only a <c>paused</c> run can be resumed:
    /// reviving a terminal run (completed/error/rejected/rolled_back) would
    /// re-offer a rejected action for approval or re-apply rolled-back side
    /// effects, and restarting an already-<c>running</c> run would race. Returns <c>null</c>
    /// (no state change) when the run is missing or not paused — the caller turns
    /// that into a clear error.
    /// </summary>
    abstract resume: id: string -> JS.Promise<ExecutionState option>
    /// <summary>
    /// Decide what to do with the next tool call or step. The host allocates and
    /// passes <c>seq</c> (not an in-memory cursor), so this is safe across hibernation
    /// and concurrent executions.
    /// <br /><br />
    /// If the execution is no longer "running" (already paused/terminal), every
    /// call gets a pause decision and nothing is recorded — so model code that
    /// swallows the pause sentinel can't drive further side effects.
    /// <br /><br />
    /// Replay: a log entry at <c>seq</c> must match connector + method + args
    /// (divergence is a hard error). Applied → replay its result (ephemeral
    /// entries re-execute instead). Pending → it was just approved, execute it.
    /// Executing (crashed mid-call) / reverted → treat as a fresh call.
    /// <br /><br />
    /// New call: step or read → execute (logged "executing" until recordResult).
    /// Approval-required → record pending, pause.
    /// </summary>
    abstract decide: executionId: string * seq: float * connector: string * ``method``: string * args: obj * requiresApproval: bool * ?ephemeral: bool -> JS.Promise<ToolDecision>
    /// <summary>
    /// Record the real result of an executed call or step. Ephemeral entries are
    /// marked applied but their result is never stored (they re-execute on
    /// replay).
    /// <br /><br />
    /// A non-ephemeral result that is too large / unserializable cannot live in
    /// the durable log (truncating it would corrupt replay), so the execution is
    /// marked failed with a model-actionable error — recorded on the execution
    /// rather than thrown, because a rejection across the facet RPC boundary
    /// would surface as an unhandled rejection on the host. The entry stays
    /// "executing" (its side effects already happened) and the run can make no
    /// further progress.
    /// </summary>
    abstract recordResult: executionId: string * seq: float * result: obj -> JS.Promise<unit>
    /// <summary>
    /// Mark the run completed with a final result. Replay never needs the final
    /// result (a resume re-derives it), so an oversized/unserializable result is
    /// replaced with a placeholder note in the audit trail rather than failing a
    /// run that genuinely completed.
    /// </summary>
    abstract complete: executionId: string * result: obj * ?logs: string[] -> JS.Promise<unit>
    /// <summary>
    /// Mark the run errored.
    /// </summary>
    abstract fail: executionId: string * error: string * ?logs: string[] -> JS.Promise<unit>
    /// <summary>
    /// List pending actions awaiting approval. With an <c>executionId</c>, scopes to
    /// that run; without one, aggregates across every <b>paused</b> run (newest
    /// first) — so an approval UI sees every awaiting-approval run, not just
    /// whichever happened to be started/resumed last. (Defaulting to a single
    /// "current" run would drop pending actions when multiple runs are in flight.)
    /// <br /><br />
    /// Only <b>paused</b> runs are considered: a non-paused run can retain a stale
    /// "pending" log entry (e.g. a resume diverged before reaching it, ending the
    /// run as <c>error</c> while the later entry stays <c>pending</c>). Such an entry isn't
    /// actionable — approving it is a no-op — so it must not clutter the queue.
    /// </summary>
    abstract listPending: ?executionId: string -> JS.Promise<PendingAction[]>
    /// <summary>
    /// Reject a pending action. Ends the execution with an error.
    /// <br /><br />
    /// Returns whether it actually terminated the run: <c>false</c> when the seq isn't
    /// pending (a stale/duplicate reject — e.g. the action was already handled by
    /// another tab), so the caller doesn't tear down a run that's still live.
    /// <br /><br />
    /// Rejection does NOT undo actions already applied earlier in the same run —
    /// call <c>rollback()</c> for that. See docs/codemode/approvals.md.
    /// </summary>
    abstract reject: seq: float * executionId: string -> JS.Promise<bool>
    /// <summary>
    /// Expire non-terminal runs whose last state change is older than
    /// <c>maxAgeMs</c>:
    /// <br /><br />
    /// - <c>paused</c> (awaiting approval) runs are marked <b>rejected</b>. A
    ///   never-answered approval would otherwise live forever — paused runs are
    ///   deliberately exempt from retention pruning.
    /// - <c>running</c> runs are marked <b>error</b>. A run only stays <c>running</c> with a
    ///   stale <c>updated_at</c> when the host died mid-pass (every decide/record
    ///   touches the row), and such a run can never be resumed — without expiry
    ///   it would be unreclaimable and exempt from pruning forever.
    /// <br /><br />
    /// Returns the expired execution ids so the host can fire the connectors'
    /// <c>disposeExecution</c> for each. Each status flip is conditional on the
    /// status it observed, so an id is only returned (and disposed) when this
    /// call actually terminated the run.
    /// </summary>
    abstract expirePaused: ?maxAgeMs: float -> JS.Promise<string[]>
    /// <summary>
    /// Return applied connector actions (not steps) in reverse order. Reads are
    /// included but are harmless — the host's revertAction no-ops when a tool has
    /// no <c>revert</c>, and only entries that actually reverted are marked.
    /// </summary>
    abstract actionsToRevert: executionId: string -> JS.Promise<ToolLogEntry[]>
    /// <summary>
    /// Mark an action reverted after the proxy tool has reverted it.
    /// </summary>
    abstract markReverted: seq: float * executionId: string -> JS.Promise<unit>
    /// <summary>
    /// Mark a run as rolled back once the proxy tool has finished reverting its
    /// actions, so the execution status reflects the rollback (rather than staying
    /// "completed"/"error" with some entries quietly flipped to "reverted").
    /// </summary>
    abstract markRolledBack: executionId: string -> JS.Promise<unit>
    abstract getExecution: id: string -> JS.Promise<ExecutionState option>
    /// <summary>
    /// List executions, newest first. Optionally cap the number returned.
    /// </summary>
    abstract listExecutions: ?limit: float -> JS.Promise<ExecutionState[]>
    /// <summary>
    /// Delete one execution. Returns whether it existed.
    /// </summary>
    abstract deleteExecution: id: string -> JS.Promise<bool>
    /// <summary>
    /// Delete terminal (completed/error) executions, keeping the newest <c>keep</c>.
    /// Running/paused executions are never deleted. Returns the count removed.
    /// </summary>
    abstract pruneExecutions: ?keep: float -> JS.Promise<float>
    /// <summary>
    /// Promote an execution's code to a saved, addressable snippet. This is the
    /// "save what ran" hook — the developer calls it (via runtime.saveSnippet)
    /// after a script proves useful, so the model can re-run it later with
    /// <c>codemode.run(name)</c>. The execution is named explicitly (its id comes from
    /// the tool's output or <c>listExecutions()</c>). The execution's recorded
    /// connector requirements carry over to the snippet so a later run can verify
    /// they are still configured.
    /// </summary>
    abstract saveSnippet: name: string * options: SaveSnippetOptions -> JS.Promise<Snippet>
    abstract getSnippet: name: string -> JS.Promise<Snippet option>
    abstract listSnippets: unit -> JS.Promise<Snippet[]>
    abstract deleteSnippet: name: string -> JS.Promise<bool>
    abstract __DURABLE_OBJECT_BRAND: unit
    abstract ctx: FSharp.CloudEdge.Runtime.Workers.DurableObjectState<obj> with get, set
    abstract env: obj with get, set
    abstract alarm: (FSharp.CloudEdge.Runtime.Workers.AlarmInvocationInfo option -> JS.Promise<unit> option) option with get, set
    abstract fetch: (FSharp.CloudEdge.Runtime.Workers.Request<obj, U2<FSharp.CloudEdge.Runtime.Workers.RequestInitCfProperties, FSharp.CloudEdge.Runtime.Workers.IncomingRequestCfProperties<obj>>> -> U2<JS.Promise<FSharp.CloudEdge.Runtime.Workers.Response>, FSharp.CloudEdge.Runtime.Workers.Response>) option with get, set
    abstract connect: (FSharp.CloudEdge.Runtime.Workers.Socket -> JS.Promise<unit> option) option with get, set
    abstract webSocketMessage: Func<FSharp.CloudEdge.Runtime.Workers.WebSocket, U2<string, Fable.Core.TS.Es.ArrayBuffer>, JS.Promise<unit> option> option with get, set
    abstract webSocketClose: Func<FSharp.CloudEdge.Runtime.Workers.WebSocket, float, string, bool, JS.Promise<unit> option> option with get, set
